quests[36384] = { id = 36384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Trial", description = "Look, I didn't tell Kimzee about this because I don't want to hurt her feelings, I chose not to leave Pinchwhistle Point.\n\nSee, I've been working on a serum that I think should be able to cure the infected, but when I tried to test it I got surrounded and I injured my leg during the escape.\n\nI know I'm on the right track but I need to test it. Do me a favor and take this vial and go try it out on one of the infected outside.", progress = "Have you completed the field test, {name}?", completion = "The serum did what!??!\n\nI must have used too much growth hormone. Possibly... the mixture just needs to be shaken prior to dosage?", objectives = "Venture into Pinchwhistle Point and use the Vial of Untested Serum on an Infected Bruiser or Infected Lumberjack. Return to Krixel Pinchwhistle to report the results.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36385] = { id = 36385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the Ancients", description = "Opening the ancient tome you see that it's not actually a tome at all, but a container. Inside are four empty slots.\n\nUpon closer inspection each slot has next to it a carving of what appears to be a unique Draenor ancient, some glyphs and a receptacle used to hold a piece of the pictured ancient. There also appear to be directions to where these ancients may be found: medium timber -- Shadowmoon, Gorgrond, the Spires of Arak and Nagrand.\n\nThese are assassination instructions. From trees to kill trees.", progress = "What have you got there, commander?", completion = "So what you're saying is that this here book is actually a container to hold the remains of targets on a hit list? And the assassination was being perpetrated by another... tree?\n\nThis world is crazy.\n\nNow let's see what happens when we put all the pieces into place.", objectives = "Collect the Heart of Kuruk, the Trunk of Autuk, the Twig of Loruk, and the Roots of Hanuk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
