quests[36404] = { id = 36404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Garden", description = "This clearing is the perfect spot to grow herbs for our Garrison, there is just one little problem.  All these dang raccoons!\n\nI need you to clear them out and we can get this garden growing.", progress = "Did you get 'em?", completion = "Great work, {name}! We will get started planting the garden right away.", objectives = "Kill 8 Lunarfall Raccoons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36405] = { id = 36405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 051 - Offering to the Raven Mother 02" }
