quests[36407] = { id = 36407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 053 - Offering to the Raven Mother 04" }
quests[36408] = { id = 36408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Power Lost", description = "<The fragment gleams in the light as its aura's final pulse fades.>\n\nThe power within the fragment appears to be drained.\n\nYou recall hearing travelers speak of a local in Embaari Village who specializes in imbuing gems with magic.", completion = "What have you got here...\n\nOnly a keen eye would be able to spot the potential of this drained crystal. You may not be familiar with draenei crystals yet, but your familiarity with gems certainly shows.\n\nTell you what... if you would assist me in the troubles we're having with our local defense crystals I'd gladly share some of my own expertise in jewelcrafting with you.", objectives = "Find someone in Embaari Village well-versed in gemology and magic.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36409] = { id = 36409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoration", description = "As mentioned, our larger defense crystals have been drained of power, creating gaps in our defenses. The crystal you brought me is only a reminder of the severity of this situation. It's Shadowmoon magic to blame, I'm sure of it.\n\nOne of our rangari scouts spotted an orc fleeing north, past Palemoon Village, and into the valley beyond. Go, find this orc, and see if you can't retrieve whatever vessel he's storing the power inside of. If we get it back, I'm sure I can restore the crystals.", progress = "The crystal's power pulses as it is carried.", completion = "You've found it! This crystal is overflowing with energy. This is definitely what we were looking for.\n\nI fear even thinking about what kind of ritual this orc was planning to undergo with the power from this crystal.\n\nYou've done a great thing for us, {class}. As promised, I would like to show you my appreciation by teaching you how to work with some of our native gems and crystals. I trust you will put the knowledge to good use.", objectives = "Retrieve the sample for Artificer Baleera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36410] = { id = 36410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 054 - Offering to the Raven Mother 05" }
quests[36411] = { id = 36411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 014 - A Lost Ring" }
quests[36412] = { id = 36412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Invasion!", description = "Scouts report that the Shadowmoon clan is buzzing like a kicked hornets' nest. Time again to earn our pay, Commander?", progress = "We must hold the line!", completion = "You were a blaze amongst our foes, Commander. It looks like we'll see another dawn in Draenor.", objectives = "Repel the Shadowmoon clan invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36413] = { id = 36413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Power Restored" }
quests[36414] = { id = 36414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Invasion!", description = "Scouts say the Shadowmoon clan looms close, ready with their necromancy. If I die and rise again, Commander, finish me quickly. I don't want to be a ghoul.", progress = "We must hold the line!", completion = "Nothing like a little righteous bloodshed, to shake the chill from these old bones.", objectives = "Repel the Shadowmoon clan invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36415] = { id = 36415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 020 - Reagent Pouch" }
quests[36416] = { id = 36416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 049 - Misplaced Scroll" }
quests[36417] = { id = 36417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Their Cold Dead Hands", description = "Those ogres took all of my hexweave!\n\nI kept it hidden at the bottom of my bag. How could they possibly know of its importance?\n\nIf they discover even a portion of hexweave's properties, it means trouble for us all.\n\n{name}, this is a Frostwolf problem. It requires a Frostwolf solution.\n\nWill you help me?", progress = "Well, is it done?", completion = "This looks to be all of the cloth, but it appears that they tried to rip and pull the magic out by physical force. I think I see teeth marks...", objectives = "Collect 10 Damaged Hexweave from Bladespire Ogres.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36418] = { id = 36418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 013 - Dark Grimoire" }
quests[36419] = { id = 36419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dyed in the Fur", description = "I can't believe they tried to physically rip the magic out of the material!\n\nIt seems we were never in danger of my secrets falling into the wrong hands after all. Better safe than dead...\n\nIn return for your help, I will share with you my methods of fusing magic to cloth.\n\nFlytrap Ichor is very rare in this region, but I do have a bit in reserve. Take this woven fur and dip it in the ichor here. You will see for yourself what all of the fuss is about.", progress = "Has the cloth been enchanted?", completion = "There, you're on the path to becoming a true Hexweave tailor.\n\nDo not share the secrets I've shown you here with anyone.", objectives = "Use Trega's Flytrap Ichor to create a Swatch of Hexweave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36420] = { id = 36420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 011 - Garrison Supplies" }
quests[36421] = { id = 36421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 024 - Sun-Touched Cache" }
quests[36422] = { id = 36422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 029 - Sun-Touched Cache" }
quests[36423] = { id = 36423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pets Versus Pests", description = "I've been trying to get this place ready for your pets, but we've uncovered some rude pests while building the garrison.  I tried to take care of them myself, but they are too tough for my meager team.\n\nThere's an angry carrot in the garden, an enormous rat eating our food rations, and an ornery water creature harassing the fishermen.  If you can take care of them, I'll be free to finish up my work on your menagerie.", progress = "Any luck?", completion = "Thank you, {name}.  Let's see if your pets like their new space!", objectives = "Defeat the three pests in your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36424] = { id = 36424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 059 - Sun-Touched Cache" }
quests[36425] = { id = 36425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Punt", description = "<A sweaty, pulsing egg - no doubt flush with ravager larvae.\n\nA swift kick should take care of these.>", objectives = "Kick 10 Ravager Eggs in Camp Thornscar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36426] = { id = 36426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dueling Orbs" }
quests[36427] = { id = 36427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise and Fall of Barov Industries: Alexi Barov", description = "[PHYLARCH ACQUISITION TEXT GOES HERE]", sourceObjective = "Accept the Blood Oath of Blademaster Na'Shra.", completion = "\"The brothers united once more,\" he said.\n\n\"A world full of untold riches to plunder,\" he said.\n\n\"Wealth beyond imaging,\" he said!\n\nAnd then he proceeded to drop a log on top of me.\n\n\"There can only be one CEO of Barov Industries,\" he said.\n\nAt least we can agree on that...", sourceObjectiveStatus = "unverified-source-field" }
quests[36428] = { id = 36428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curing With Force", description = "The infection is getting stronger so I made some adjustments and I'm pretty sure I have the right formula now.\n\nIt should now work but it needs to have less competition with the infected blood for it to have any effect.\n\nThis means you will need to weaken them before you apply the serum for it to function properly.\n\nThe infection is getting more advanced and will soon be untreatable so we have this one shot to save as many as we can.", progress = "Any progress to report with that cure?", completion = "Yea! Great work, {name}!\n\nI've already heard from the survivors and they're glad for this second chance at life.\n\nYou made a real difference today!", objectives = "Cure 6 Infected Goblins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36429] = { id = 36429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise and Fall of Barov Industries: Weldon Barov", description = "[PHYLARCH ACQUISITION TEXT GOES HERE]", sourceObjective = "Accept the Blood Oath of Blademaster Na'Shra.", completion = "\"The brothers united once more,\" he said.\n\n\"A world full of untold riches to plunder,\" he said.\n\n\"Wealth beyond imaging,\" he said!\n\nAnd then he proceeded to drop a log on top of me.\n\n\"There can only be one CEO of Barov Industries,\" he said.\n\nAt least we can agree on that...", sourceObjectiveStatus = "unverified-source-field" }
quests[36430] = { id = 36430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 18" }
quests[36431] = { id = 36431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Soul-twister Torek" }
quests[36432] = { id = 36432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking the Scout", description = "We are still trying to locate all of our scouts out in the field. One of these, Altauur, enjoys handling the more dangerous missions.\n\nHe has not checked in and I feel we should check to make sure he has not taken on more than he can handle.", completion = "D'kaan worried about me? He is more worried I will be chased back to the camp with one of those giant beasts in tow. Still I could use your help here...", objectives = "Find Altauur at Dionor's Demise in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36433] = { id = 36433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 008 - Smuggled Apexis Artifacts" }
quests[36434] = { id = 36434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Penny From Heaven", description = "<Durotan looks at you curiously.>\n\nThose from your world are not much for subtlety, are they?\n\nGo on ahead and greet our new companion. We will join you as soon as we can make ready.", completion = "Ahh, there y'are!\n\nPenny Clobberbottom reportin' for duty, commander.", objectives = "Speak to Penny Clobberbottom at Beastwatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36435] = { id = 36435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unintelligible Intelligence", description = "The notes are unreadable, but based on previous experience, the text appears to be very similar to standard Orcish.\n\nIt is possible that the notes could contain strategic information. Perhaps it would be of great value to the Frostwolf Orcs.\n\nSomeone in Wor'gol might be able to help interpret the text.", progress = "<Raleigh looks up from the scrolls.>\n\nCommander {name}, what brings you to Wor'gol?!", completion = "We have been studying these orcish texts feverishly since our arrival here. Allow me a moment to translate this for you.\n\nHmmm... The notes appear to contain a list of names.", objectives = "Look around Wor'gol for someone who can help translate the notes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36436] = { id = 36436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plant Pruning", description = "There may be more to this aberrant growth than it seems, but we will need to clear the way a bit before we can get to the bottom of this, yes?\n\nI suggest clearing out some of the angrier defenders to be on the safe side.", progress = "How goes the pruning {class}?", completion = "I have slain quite a few as well but they continue to spring up here.\n\nWe will need another solution...", objectives = "Kill 12 defenders at Dionor's Demise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36437] = { id = 36437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambassador to the Ancient", description = "It appears that a genesaur was killed here not long ago and this growth has sprung up.  It is stirring up the local monsters and I fear for our outpost.\n\nThere is a strange ancient that wallows in grief here and is not hostile. Perhaps you could \"harvest\" its story?", completion = "So the normal ebb and flow of battle has been disrupted by the saberon. I do not think it wise to leave things as such.\n\nWe should see about infiltrating the saberon and setting things right.", objectives = "Talk to Birchus at Dionor's Demise in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36438] = { id = 36438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beatface vs. Boulder", description = "The saberon took their treasure up the rise and barricaded themselves in after Birchus attacked. It will be difficult to get in but I hear you have resources to handle this.\n\nOne of their entrances is covered with a large boulder. Too large for you or I, but perhaps an ogre with a large enough hammer could break it. I think you know who I am talking about...", completion = "You have strong friends {name}. We must make haste before the plants realize the way is open.", objectives = "Break the boulder barrier using Beatface the gladiator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36439] = { id = 36439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredder vs. Saberon", description = "The saberon took their treasure up the rise and barricaded themselves in after Birchus attacked. It will be difficult to get in but I hear you have resources to handle this.\n\nOne of their entrances is covered with tough vegetation. I believe you have a mechanical solution to this problem in the form of a shredder. I think you know what to do...", completion = "Your machine is brutish but effective, well done {name}. We must make haste before the plants realize the way is open.", objectives = "Break the vine barrier using your shredder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36440] = { id = 36440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saberon Population Reduction", description = "We are closer to our goals but a host of sharp toothed saberon bar our way.\n\nIf we are to get anywhere up here, some of the more aggressive ones will need to be put down I think.", completion = "Many are finding bolt-holes to weather your storm, friend. That should keep them out of our way.", objectives = "Slay 10 saberon at Steamscar Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36441] = { id = 36441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Property", description = "You are attracted by a low green glow to the container.  Inside there is a glowing bundle of herbs that was most likely stolen from the overgrowth below.\n\nIt would be best to collect all of these so the saberon don't continue their dabbling in plant magic and irritating the nearby magnaron.", progress = "The saberon should definitely NOT have any of the herbs you have found!", completion = "A good catch discovering those herbs {name}. We cannot allow them to continue using these. Who knows what it might set off.", objectives = "Find 8 Herb Bundles in saberon stashes at Steamscar Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36442] = { id = 36442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Death Bloom", description = "Your work has born fruit. Inside the nearby cave a powerful saberon shaman is learning to channel the genesaur magic using the Death Bloom we seek. The solution is before us: kill the shaman, take the Death Bloom, return it to Birchus. That should improve the safety of our outpost.", progress = "Do you have something for me little beast?", completion = "You have... you have brought me the bloom. At last my purpose can be fulfilled!", objectives = "Take the Death Bloom from Smokemaster Snarl in Steamscar Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36443] = { id = 36443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laying Dionor to Rest", description = "You have given me a tremendous gift with this bloom. I can finally send Dionor back to the Overgrowth for good and end this nightmare. All that remains is the ritual... stay and behold something you will never see again in your lifetime...", completion = "At last it is done.  Dionor has left and his spawn shall follow him in due time.\n\nI grow weary of this conflict and the desire to return to the Overgrowth has left me.\n\nPerhaps I will travel beyond these lands and see what other surprises you little beasts have to share...", objectives = "Watch Birchus's ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36444] = { id = 36444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 006 - Iron Horde Explosives" }
quests[36445] = { id = 36445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 015 - Iron Horde Spear" }
quests[36446] = { id = 36446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 016 - Outcast's Pouch" }
quests[36447] = { id = 36447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 020 - Outcast's Basket" }
quests[36448] = { id = 36448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reduction in Force", description = "I was a fool to trust him after the fiasco over the Barov family fortune! What I should have done is killed him the first chance I had.\n\nAnd now he thinks he's going to plumb this land for all that it's worth and cut me out?!\n\nNo, dear brother, not this time! There can only be one CEO of Barov Industries and it will be me.\n\nMy peasant friend, you must do me this service. Find my brother, Alexi, and serve him a notice of termination!\n\nYou will likely find him out in the wilds, near small timber.", progress = "Did you deliver the... notice of termination?", completion = "<Weldon holds Alexi's head up to his face and begins speaking.>\n\nYou no-good, backstabbing son-of-a-goat! Your greed is only surpassed by my own!\n\nAs for you my peasant friend, you have served me well. Here are your just rewards!", objectives = "Collect the Head of Alexi Barov.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36449] = { id = 36449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reduction in Force", description = "I was a fool to trust him after the fiasco over the Barov family fortune! What I should have done is killed him the first chance I had.\n\nAnd now he thinks he's going to plumb this land for all that it's worth and cut me out?!\n\nNo, dear brother, not this time! There can only be one CEO of Barov Industries and it will be me.\n\nMy peasant friend, you must do me this service. Find my brother, Weldon, and serve him a notice of termination!\n\nYou will likely find him out in the wilds, near small timber.", progress = "Has my brother been served the notice of termination yet?", completion = "<Alexi holds Weldon's head up to his face and begins speaking.>\n\nYou no-good, backstabbing son-of-a-goat! Your greed is only surpassed by my own!\n\nAs for you my peasant friend, you have served me well. Here are your just rewards!", objectives = "Collect the Head of Weldon Barov.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36450] = { id = 36450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 028 - Sethekk Ritual Brew" }
quests[36451] = { id = 36451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 033 - Craftsman's Hammer" }
quests[36452] = { id = 36452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spawn Tracking & Spell Visuals: Do They Work?", description = "Here's some text.", objectives = "Use the What's It to see a Spell Visual play through the magic of Spawn Tracking tech.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36453] = { id = 36453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 038 - Coinbender's Payment" }
quests[36454] = { id = 36454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 039 - Drypeak Mushrooms" }
quests[36455] = { id = 36455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 040 - Waterlogged Satchel" }
quests[36456] = { id = 36456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 045 - Shredder Parts" }
quests[36457] = { id = 36457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bypassing Security", description = "Oh, my goodness!\n\nThis is a list of captives, it appears they may be awaiting transfer... or possibly even execution.\n\nThere is one name on this list that I do recognize: my master!\n\nI have been awaiting his return, but now it appears that he may have fallen into enemy hands.\n\nThis is a disaster! Please, {name}, we must rescue him.\n\nAccording to the notes, he has been taken to Grom'gar, located far east of here.\n\nOne moment... I think I may have just the thing to help you break in undetected...", completion = "You know the trick to fooling a bunch of Orcs? Every once in a while you've got to be holding all the cards!", objectives = "Infiltrate Grom'gar using Raleigh's Prestige Card.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36458] = { id = 36458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 055 - Abandoned Mining Pick" }
quests[36459] = { id = 36459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 056 - Dislodged Saw Blade" }
quests[36460] = { id = 36460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Another Stick in the Wall", description = "So, get this.\n\nAs I was flyin' in, I took the opportunity to scope out what might be a defensible position.\n\nJust on the other side o' these boulders is an ideal clearing to hole up in. I even brought a set of blueprints to get us all settled in!\n\nThat's not too presumptuous, is it?\n\nAnyway, whenever you're ready just hit this plunger!", completion = "Perhaps this little creature will earn her keep after all.", objectives = "Use Penny's Plunger to blow up the Rock Wall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36461] = { id = 36461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locating the Lapidarist", description = "Are you sure I can't take this off your hands? I'll give you a fair price!\n\nAlright, alright... if you insist on finding the owner, you might want to try visiting Wor'gol.\n\nRumor has it, there is a master craftsman, skilled in manipulating precious metals and stones.\n\nBut, if you change your mind, you know where to find me....", objectives = "Search for the owner of the pendant in Wor'gol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36462] = { id = 36462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 012 - Admiral Taylor's Coffer" }
