quests[36468] = { id = 36468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Treasure Map" }
quests[36469] = { id = 36469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pets Versus Pests", description = "I been tryin' ta get dis place ready for your pets, but we uncovered some rude pests while buildin' da garrison.  I tried takin' care o' dem myself, but they be too tough for my little friends.\n\nBeat da angry carrot in da garden, da rat eatin' our food, and da ornery water creature harassing da fishermen.  If you can do it, I be free to finish up da work on your menagerie.", progress = "How'd you fare, {name}?", completion = "Nice job, brudda.  I hope your pets be likin' dere new home.", objectives = "Defeat the three pests in your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36470] = { id = 36470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 006 - Rotcap" }
quests[36471] = { id = 36471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Darkmoon Challenger!", description = "Look at me, now look at my horse, now look back at me, are I not the most impressive battler of pets that you have ever seen?\n\nLook now at my compatriot over there. Is he on a horse? Of course not! Is his hat made of fireworks? Not in a million years! Everything about me is more impressive, from my coat color to my last name, which I made myself.\n\nDare you step up to the might of Christoph Willikens Dennis Ragnaros VonFeasel the First?\n\nI can see you trembling!", progress = "Ready, eh? Put up your cat's tiny dukes!", completion = "Next time I won't go so easy on you!", objectives = "Defeat Christoph VonFeasel in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36472] = { id = 36472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 028 - Wasp Ancient" }
quests[36473] = { id = 36473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Affliction Ridge" }
quests[36474] = { id = 36474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Razorbloom", description = "The Laughing Skull shaman Kaz ran off while we were coming here.\n\nShe claimed to be looking for more of her people in the jungles to the south.\n\nDraka insisted on following her to safeguard us against betrayal.\n\nCommander, if Kaz is telling the truth, then she and Draka are going to need all the help they can get.\n\nWill you join them? They could not have gotten far.\n\nThis could prove to be the perfect test for your new shredder and lumber mill resources.", completion = "My husband sent you, didn't he?\n\nNormally I would laugh at that, but seeing these horrors, Kaz and I could use all the help we can get.", objectives = "Find Draka and Kaz at the Razorbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36475] = { id = 36475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing the Declaration", description = "Commander, you and Raleigh did a great job finding me, but I'm exactly where I need to be.\n\nWe've been working tirelessly since we got here, trying to crack these Draenic texts.\n\nI really thought I was gonna get the scrolls, but they nabbed me at the last possible second!\n\nPlease, you've gotta help me out... up the hill to the east, you'll find the Master Siegesmith's tent.\n\nIf you can grab the documents out of his chest, possibly this key too, I'll finally have enough to translate their languages.", progress = "A book of poems? I'll let you hang onto that one for now....", completion = "{name}, this is it, THIS IS IT! Just give me a moment while I look through these.\n\nHmm... I think there are a few things here that you may find very useful. Here, take these plans with you.\n\nDon't worry about me, commander. I'm just gonna take another look around before I sneak out of here.", objectives = "Loot the contents of Master Siegesmith Uratok's Strongbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36476] = { id = 36476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "South Gronn Canyon" }
quests[36477] = { id = 36477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Promises", description = "A heavily-scratched ring, faintly stained with blood.\n\nSomeone at the Darkmoon Faire might be able to provide more information about this item.", completion = "Ah, I see that you've found my lovelies. Beautiful, aren't they? It's a shame that the process drives them so... insane.\n\nThe ring is yours to keep, of course. Can you hear them whisper? Marvelous.", objectives = "Find someone at the Darkmoon Faire that might be interested in the ring.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36478] = { id = 36478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette 020 - Shadowbark" }
quests[36479] = { id = 36479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette 021 - Nightmaw" }
quests[36480] = { id = 36480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valley of Destruction" }
quests[36481] = { id = 36481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebird's Challenge", description = "You're ready to fly high and give the Firebird's challenge a shot? That's great!\n\nSimply collect 15 rings to win! Speak to me when you're ready for takeoff!", progress = "How was the flight?", completion = "Wow, great flying out there, ace! Here's your prize!", objectives = "Collect 15 rings while flying.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36482] = { id = 36482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Green Ogron?", description = "Kaz always told me green ogron are bad.\n\nThe botani here have a green ogron and it is mean.\n\nIt was strong enough to take out my dad's entire hunting party.\n\nAre you strong enough to kill it?", completion = "Yay! Burn the bad guy! Burn him a lot!", objectives = "Kill the Infested Ogron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36483] = { id = 36483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Roundup", description = "Looks like we've got some visitors in the battle pen today, and they're looking for a fight.  Why don't you show 'em how a master of pet battles handles <himself/herself>?", progress = "Those pets looked tough.  How'd you do?", completion = "I knew you could do it, kid.", objectives = "Defeat the pets in the battle area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36488] = { id = 36488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Dwarves", description = "Cutter is on the trail of the artifact the dwarves stole. He has the nose of a wolf when it comes to hunting in the jungle.\n\nFollow the canyons south until you find him.\n\nIt would seem the wolf queen and I are going to do more damage here before we leave.\n\nWe will follow as quickly as we can.", completion = "Wow. Those... \"dwarves\"... sure do know how to make both botani AND goren mad.", objectives = "Find Cutter at Bastion Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36489] = { id = 36489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Pit", description = "The Iron Horde are stockpiling their weapons and ammunition outside of the Foundry. Their campaign throughout Draenor has left their caches vulnerable. Get in there and cause as much chaos as you can, and while you're at it use some of that ammunition against them if they're just going to leave it lying around!", objectives = "Destroy Iron Horde weapons cache and take out as many of them as you can.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36490] = { id = 36490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Pillars of Fate" }
quests[36491] = { id = 36491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Pillars of Fate" }
quests[36492] = { id = 36492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Pet Battle" }
quests[36493] = { id = 36493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Can Open Othaar's Door" }
quests[36494] = { id = 36494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News from Talador", description = "Rokhan sends word that you are needed at Frostwall. The Iron Horde have landed on the shores of Talador.", completion = "Welcome back, mon.", objectives = "Speak to Rokhan at your garrison in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36495] = { id = 36495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News from Talador", description = "Bodrick Grey sends word from your garrison that they have spotted a fleet of Iron Horde at the shores of Talador.\n\nWe must not allow them to destroy Shattrath.", completion = "Welcome back, {name}.", objectives = "Speak to Bodrick Grey at your garrison in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36496] = { id = 36496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lumber Mill", description = "The Rangari have been here for a tick, and they hear tell from the Laughing Skull o' a place called Tangleheart.\n\nSeems some really bad ancients come from there, and botani use a kind o' sap to grow them quickly.\n\nI think we could use that for yer outpost. Hey, wood is wood, right?\n\nI'll meet ya there.", sourceObjective = "Speak to Glirin outside Tangleheart.", sourceObjectiveStatus = "unverified-source-field" }
quests[36498] = { id = 36498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Horde Invasion", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Vindicator Maraad at the Shattered Beachhead in Blasted Lands.\n\nUse the portal at the Wizard's Sanctum in Stormwind to head directly to the front line.\n\nThis new threat is known only as the Iron Horde. They have taken over the Dark Portal and must be stopped.\n\nFor the glory and honor of the Alliance!", completion = "The situation here is dire, {name}. We have much to discuss.", objectives = "Speak with Vindicator Maraad at the Shattered Beachhead in Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36499] = { id = 36499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Horde Invasion", description = "All able bodied members of the Horde are hereby ordered to report to Thrall in Blasted Lands.\n\nUse the portal at the Cleft of Shadow in Orgrimmar to head directly to the front line.\n\nThis new threat is known only as the Iron Horde. They have taken over the Dark Portal and must be stopped\n\nDestiny calls!", completion = "The situation here is dire, {name}. We have much to discuss.", objectives = "Speak with Thrall at the Shattered Landing in Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36500] = { id = 36500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Razorbloom" }
quests[36501] = { id = 36501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Horde Invasion", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Vindicator Maraad at the Shattered Beachhead in the Blasted Lands.\n\nYou can reach the docks outside Northwatch Hold by taking a boat from Booty Bay to Ratchet and traveling south along the coast.\n\nFor the glory and honor of the Alliance!", sourceObjective = "xxxx", sourceObjectiveStatus = "unverified-source-field" }
quests[36502] = { id = 36502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Biolante", description = "Defeating Biolante has yielded you a trophy worthy of showing off at your outpost. \n\nReturn this to Maraad to increase your glory!", completion = "I've seen plant life mimic the vicious hydra before, but to improve on the design? Only in Gorgrond... excellent work {name}.", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36503] = { id = 36503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Biolante", description = "Defeating Biolante has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", completion = "In this land even the plants turn into vicious monsters. Biolante was one of the worst, still as a plant until you were too close.\n\nA fitting end to such a beast...", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36504] = { id = 36504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evermorn Springs" }
quests[36505] = { id = 36505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Warrior's Shroud", description = "Although this cloak has seen better days, the workmanship is still quite impressive. Any normal cloak would have most certainly fallen apart by now.\n\nPerhaps one of the Frostwolf orcs within Wor'gol would be willing to help you repair it.", progress = "Greetings, {race}. do you require any repairs?", completion = "This is a fine cloak! Sadly, we no longer have the resources to make them like this.", objectives = "Locate a Frostwolf leatherworker in Wor'gol that can help you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36506] = { id = 36506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Orc Super Caster Loot" }
quests[36507] = { id = 36507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Orc Skeleton" }
quests[36508] = { id = 36508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is This One of Yours?", description = "I found this one skulking nearby. She claims to be an ally of yours.\n\nIs this true? Or does she cook slowly over my fire?", completion = "Thank you for vouching for me, commander.", objectives = "Talk to Rexxar and vouch for Rangari Erdanii.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36509] = { id = 36509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Hydra Treasure Pile" }
quests[36510] = { id = 36510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Ammonite", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Frostfire Ridge for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", progress = "Anything biting?", completion = "These will do nicely, {name}!  Thank you!", objectives = "Ron Ashton wants you to collect 10 Fire Ammonite Eggs from Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36511] = { id = 36511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jawless Skulker", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Gorgrond for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", progress = "Anything biting?", completion = "These will do nicely, {name}!  Thank you!", objectives = "Ron Ashton wants you to collect 10 Jawless Skulker Eggs from Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36512] = { id = 36512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Together We Are Strong", objectives = "Auchindoun would have fallen to the demons if it weren't for you. Even the blood elves would not have been enough. I don't know how I could possibly ever repay you.\n\n<Tuulani's face lights up.>\n\nThat's it! We're kindred spirits, {name}. I can feel it! How about I stick around with you?\n\nI'll still have to attend to my duties at Auchindoun, but I can handle it. What do you say, {name}? It'll be great!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36513] = { id = 36513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fat Sleeper", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Nagrand for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", progress = "Anything biting?", completion = "These will do nicely, {name}!  Thank you!", objectives = "Ron Ashton wants you to collect 10 Fat Sleeper Eggs from Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36514] = { id = 36514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Lake Sturgeon", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Shadowmoon Valley for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", progress = "Anything biting?", completion = "These will do nicely, {name}!  Thank you!", objectives = "Ron Ashton wants you to collect 10 Blind Lake Sturgeon Eggs from Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36515] = { id = 36515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackwater Whiptail", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Talador for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", progress = "Anything biting?", completion = "These will do nicely, {name}!  Thank you!", objectives = "Ron Ashton wants you to collect 10 Blackwater Whiptail Eggs from Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36516] = { id = 36516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut 'Em Out!", description = "After all that you've done for us, I would love to help you. Regrettably, I don't have the materials I would need to repair this perfectly.\n\nUse my knife to gather a few hides from the clefthoof that roam near the spire and find some sootweed pitch to properly cure them.\n\nUnfortunately, those miserable ogres have taken up residence in the only place that I know of sootweed to grow. You may be in for a fight {name}.\n\nReturn to me if you can obtain these and I will gladly help you repair your cloak.", progress = "Were you able to obtain the materials, {name}?", completion = "You are covered in soot from head to toe, {name}!\n\nAs promised, I will help you repair your cloak. I have a few other items here which you might find useful as well.\n\nCome back and see me any time!", objectives = "Obtain the materials needed to repair the cloak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36517] = { id = 36517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssal Gulper Eel", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Spires of Arak for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", progress = "Anything biting?", completion = "These will do nicely, {name}!  Thank you!", objectives = "Ron Ashton wants you to collect 10 Abyssal Gulper Eel Eggs from Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36518] = { id = 36518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The True Path", objectives = "Wow... I've never seen anyone fight like that. That was... impressive.\n\nI'm in no shape to join Lady Liadrin and the others at Auchindoun now. You have an entire fortress on this world, though. Could I go there and rest awhile? Maybe repair my armor?\n\nI'll stick around and join your forces as a token of my gratitude. Liadrin won't mind... we're all on the same team, right?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36519] = { id = 36519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The True Path", objectives = "I have never seen anyone fight like that, \n.\n\nI am regrettably in no condition now to join the Auchenai in defending Auchindoun. I have heard stories of your fortress in Shadowmoon Valley. Could I go there and repair my armor?\n\nPerhaps... I could stay there a while longer than that? I feel there is much you could teach me.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36520] = { id = 36520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailthrasher Basin" }
quests[36521] = { id = 36521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Rylak Egg" }
quests[36522] = { id = 36522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solidarity in Death", objectives = "I may have fallen, but I will not be forgotten.\n\nI implore you to allow me to stay here and serve in your army. Bralok took my life, but my spirit stands strong before you.\n\nI need to stop the Iron Horde, {name}, and I know you are the only one that can help me do that.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36523] = { id = 36523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Green Ogron?", description = "Them botani got themselves a green ogron. A green ogron!\n\nI mean I may not know much about plant people but that canno' be a good thing.\n\nThink ya can take it in a fight?", completion = "Is it still twitchin'? I think I saw it still twitchin'.", objectives = "Kill the Infested Ogron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
