quests[36567] = { id = 36567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bigger is Better", description = "Ya know boss, I think I know how we can take this place to the next level. Bigger walls. More buildings. Some space to stretch your arms after a long day of adventuring.\n\nDon't get me wrong, it's going to take a lot of resources, but what else are these things for?\n\nWe can plot it out on the drafting table whenever you're ready. It's going to be GLORIOUS.", progress = "What ya waitin' for boss? Let's take this thing to the next level!", completion = "Now THAT'S what I'm talkin' about! Look at this place!\n\nWe've even got a pool out back. Little cold, sure, but ya can't always have a tropical paradise.", objectives = "Use the Architect Table to select your Town Hall and upgrade your garrison to Tier 2.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36568] = { id = 36568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Malgosh Shadowkeeper" }
quests[36569] = { id = 36569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unruly Visitors", description = "Looks like we've got some visitors in the battle pen today, and they're looking for a fight.  Why don't you show 'em how a master of pet battles handles <himself/herself>?", objectives = "Defeat the pets in your Garrison menagerie's battle area.Looks like we've got some visitors in the battle pen today, and they're looking for a fight. Why don't you show 'em how a master of pet battles handles <himself/herself>?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
