quests[36571] = { id = 36571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iyun Weald" }
quests[36572] = { id = 36572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tangleheart Return", description = "Hey there, peach. We've got the lumber mill good and ready, but we gotta find a way of choppin' wood fast out here.\n\nThe Laughing Skull talked about Tangleheart, where the botani grow things quick as a quark.\n\nI'm headin' there now.", sourceObjective = "Speak to Penny Clobberbottom outside Tangleheart.", sourceObjectiveStatus = "unverified-source-field" }
quests[36573] = { id = 36573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike While the Iron is Hot", description = "With the Heart of the Mangaron, we wield a powerful weapon against the Iron Horde.\n\nThey amass far to the north at the Iron Approach. This will not be easy, but we must seize the opportunity to deal a blow to the Iron Horde while we possess the artifact.\n\nWe are prepared to depart at your command. Speak with Grinslicer when you are ready.", progress = "The mysteries of this land sometimes bear fruit.", completion = "{name}, we have dealt a great blow to the forces of the Iron Horde.", objectives = "Speak to Grinslicer to fly to the Iron Approach and attack the Iron Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36574] = { id = 36574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike While the Iron is Hot", description = "With the Will of the Genesaur, we wield a powerful weapon.\n\nOur scouts have discovered an Iron Horde base, and I believe it is time to seize an opportunity.\n\nThey amass far to the north at the Iron Approach. This will not be easy, but we must deal a blow to the Iron Horde while we possess the artifact.\n\nWe are prepared to depart at your command. Speak with Grinslicer when you are ready.", progress = "The mysteries of this land sometimes bear fruit.", completion = "{name}, we have dealt a great blow to the forces of the Iron Horde.", objectives = "Speak to Grinslicer to fly to the Iron Approach and attack the Iron Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36575] = { id = 36575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike While the Iron is Hot", description = "With the Will of the Genesaur, we wield a powerful weapon.\n\nOur scouts have discovered an Iron Horde base, and I believe this is the time to seize an opportunity.\n\nThey amass far to the north at the Iron Approach. This will not be easy, but we must deal a blow to the Iron Horde while we possess the artifact.\n\nWe are prepared to depart at your command. Speak with Rangari Rajess when you are ready.", progress = "We must eradicate the Iron Horde.", completion = "We have dealt a great blow to the Iron Horde, commander. We will defeat them yet.", objectives = "Speak to Rangari Rajess to fly to the Iron Approach and attack the Iron Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36576] = { id = 36576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike While the Iron is Hot", description = "With the Heart of the Magnaron, we wield a powerful weapon against the Iron Horde.\n\nThey amass far to the north at the Iron Approach. This will not be easy, but we must seize the opportunity to deal a blow to the Iron Horde while we possess the artifact.\n\nWe are prepared to depart at your command. Speak with Rangari Rajess when you are ready.", progress = "We must eradicate the Iron Horde.", completion = "We have dealt a great blow to the Iron Horde, commander. We will defeat them yet.", objectives = "Speak to Rangari Rajess to fly to the Iron Approach and attack the Iron Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36577] = { id = 36577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flying Machine Completed" }
quests[36587] = { id = 36587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Gate Tracking" }
quests[36588] = { id = 36588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking - See Closed Chest" }
quests[36589] = { id = 36589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy Arms", description = "The burned out shell of some sort of weapon of mass destruction. It might be worth asking around your garrison to see if anyone can help get it working again.", progress = "Yo, boss. Whatchya got for me?", completion = "I think we could get into some serious trouble with this beauty!", objectives = "Look around the garrison for help with the repairs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36590] = { id = 36590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Howling Crag" }
quests[36592] = { id = 36592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bigger is Better", description = "Commander, I've been working on schematics that you might be interested in.\n\nWhat do you think about pushing out the walls and making room to get some additional structures in here? Our forces have been growing, and things are getting a little cramped, and I'd really like us to put some of those additional blueprints to use.\n\nIf you could, take a look at the plans on the table here. As soon as I have your go ahead, I'll get everyone to work immediately.", progress = "What do you think? Time for an upgrade?", completion = "MUCH better!  A lot less bumping into walls to be sure.\n\nThere should be room to get in another building or two now. We can get the additional construction going whenever you're ready - just point me at anything you're interested in on the table here.", objectives = "Use the Architect Table to select your Town Hall and upgrade your garrison to Tier 2.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36594] = { id = 36594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Spare\" Parts", description = "I've never seen anything like this before! No problem though, boss man. If it can be used to blow things up, I can get it working again.\n\nWe are definitely going to need some parts--some sort of ammunition wouldn't hurt either.\n\nSounds like those Iron Horde guys over yonder are no stranger to things that go boom.\n\nTake these tools with you and let's see if we can't commandeer us some spare parts!", progress = "Got the stuff yet boss?", completion = "What did you think of my rapid disassembly tech? Pretty effective, yeah?", objectives = "Recover 20 Black Iron Shells and 50 Siege Cannon Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36595] = { id = 36595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Drew Aggro...culture", description = "What you saw was the wake of the genesaur, Iyu. It was chasing this mechanical monstrosity and the person who drove it.\n\nI believe the pilot of this vessel is still alive and trapped within the ruins of the camp.\n\nIf you wish them to be recovered, I recommend doing so now.", completion = "Ah perfect. I'll get this up an' runnin' in no time.", objectives = "Find the pilot of the Dark Iron tank.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36596] = { id = 36596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Iron Horde Weapon Stash" }
quests[36597] = { id = 36597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Berthora" }
quests[36600] = { id = 36600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Riptar" }
quests[36601] = { id = 36601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News from Nagrand", description = "One of your soldiers stopped by asking for you while you were out. Something about a caravan heading out to Nagrand.\n\nWhatever it was, it can't have gone well for them. That's Warsong territory.", completion = "Commander. Good to have you back.\n\nWe've got some movement in Nagrand. Let me fill you in on the details.", objectives = "Speak to Bodrick Grey at your garrison in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36602] = { id = 36602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News from Nagrand", description = "One of your soldiers stopped by asking for you while you were out. Something about a caravan heading out to Nagrand.\n\nWhatever it was, it can't have gone well for them. That's Warsong territory.", completion = "Boss-mon. Good to have ya back.\n \nWe been seein' some movement in Nagrand. Let me give ya the details.", objectives = "Speak to Rokhan at your garrison in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36603] = { id = 36603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brimstone Springs" }
quests[36604] = { id = 36604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Dark Iron Emergency Pack" }
quests[36605] = { id = 36605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Dark Iron Remains" }
quests[36606] = { id = 36606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News from Nagrand", description = "Welcome back, <sir/mam>.\n\nOne of Bodrick's men delivered a message about a caravan being dispatched for Nagrand. He's awaiting your approval on a new outpost.\n\nI've been hearing whispers around camp about Nagrand. They say it's Warsong territory. They might need your help <sir/mam>.", completion = "Commander. Good to have you back.\n\nWe've got some movement in Nagrand. Let me fill you in on the details.", objectives = "Speak to Bodrick Grey at your garrison in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36607] = { id = 36607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News from Nagrand", description = "Welcome back, <sir/mam>.\n\nOne of our shadow hunters delivered a message about a caravan being dispatched for Nagrand. Rokhan's awaiting your approval on a new outpost.\n\nI've been hearing whispers around camp about Nagrand. They say it's Warsong territory. They might need your help <sir/mam>.", completion = "Boss-mon. Good to have ya back.\n \nWe been seein' some movement in Nagrand. Let me give ya the details.", objectives = "Speak to Rokhan at your garrison in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36608] = { id = 36608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Nat Pagle", description = "Now that you have proof, we might just have a shot at convincing Nat Pagle to join us out here.\n\nLast I heard, he was in fishing with the local Angler's faction out in Pandaria.  Somewhere off the coast of  Krasarang Wilds.  Head out there, show him your catch and see if you can get him to come back with you!", progress = "You came all this way for me? Well, I am pretty important.", completion = "You came from Draenor? How does that even work?!", objectives = "Travel to the Angler's Wharf in Krasarang Wilds and talk to Nat Pagle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36609] = { id = 36609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Angler Returns", description = "What's this species, a molten catfish you say? I have never even heard of a fish like this, much less seen one in person!\n\nI have to find more fish like this, it's what I live for! And if the fishing is as good as you say it is, there is just no way I can pass this opportunity up.  Take this page from my journal as proof that you found me and I will meet you back at your Garrison.", progress = "You found Nat? The real Nat Pagle?!", completion = "We should really catch some big one's when Nat's gets here!", objectives = "Return to Rak'jin with Nat's journal page as proof that you found him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36610] = { id = 36610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gorge Spear" }
quests[36611] = { id = 36611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A True Draenor Angler", description = "If you want me to help you permanently, you have to show me a few of these big Draenor catches first.  Head out into the wild and bring me back the biggest fish you can find from all the surrounding areas.\n\nI made this custom lure for you to use, please take care of it, it's never let me down!", progress = "What did you catch?", completion = "These fish are exquisite, {name}. Great job!", objectives = "Catch a Lunker in each of the  Draenor zones and bring them back to Nat Pagle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36612] = { id = 36612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luring Nat", description = "Now that you are experienced enough with Draenor fishing, we might have a shot at convincing Nat Pagle to join us out here.\n\nIf we want Nat to actually come all the way out here, we are going to have to show him real proof of the incredible catches on Draenor.  Head out to the lava lakes here in Frostfire and see what you can do.  All that time you spend honing your skill here in Draenor should pay off now.", progress = "Any luck near those lava pools?", completion = "This will do nicely... A fish like this would be hard for anyone to deny, especially Nat!", objectives = "Catch a Molten Catfish in Frostfire Ridge and bring it back to Rak'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36614] = { id = 36614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Very Own Fortress", description = "Boss! Guess what?! I finally got that new larger draft paper in that I ordered when we first came here. And ya know what larger draft paper means?\n\nIt means I can draw a bigger fortress!\n\nAnd if I can draw it, I can certainly make it! Making's the easy part, as long as you've got a few thousand stones and logs lying around.\n\nSo whada'ya say, boss? Shall we get building?", completion = "I think I could just fall over and die happy right now. It's a dream come true!\n\nI already ordered some even larger draft paper, boss. Don't you worry...", objectives = "Gather 2000 Garrison Resources and then use the Architect Table to select your Town Hall and upgrade your garrison to Tier 3.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36615] = { id = 36615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Very Own Castle", description = "Commander! Some good news. I finally got that new larger draft paper in that I ordered when we first came here. And do you know what larger draft paper means?\n\nIt means I can draw a bigger castle!\n\nAnd if I can draw it, we can certainly make it! Making it is the easy part, assuming you have a few thousand stones and logs lying around.\n\nSo what do you say, sir? Shall we get building?", completion = "I... I think I like it. A little more blue paint, maybe some taller towers, but you can really call it home, you know?\n\nI already ordered some even larger draft paper, sir. Don't you worry...", objectives = "Gather 2000 Garrison Resources and then use the Architect Table to select your Town Hall and upgrade your garrison to Tier 3.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36616] = { id = 36616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Angler on Our Team", description = "You truly are a master fisherman!\n\nI would be delighted to join you here on Draenor and help you catch as many lunkers as you can. But first, let's grab a drink.", completion = "You truly are a master fisherman!\n\nI would be delighted to join you here on Draenor and help you catch as many lunkers as you can. But first, let's grab a drink.", objectives = "Talk to Nat Pagle and ask him to join our cause.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36617] = { id = 36617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36618] = { id = 36618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Iron Supply Chest" }
quests[36619] = { id = 36619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumber Mill" }
quests[36620] = { id = 36620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategic Choices", description = "Good to see you, commander.\n\nMy network has been keeping eyes on enemy movements. There are a couple threats I'd like to get you up to date on.\n\nDo you have a moment to look at our options?", objectives = "Choose between your strategic options.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36621] = { id = 36621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gnome Canister" }
quests[36623] = { id = 36623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Invasion!", description = "Commander, our scouts say that ogre bands march through the snow. If they want more battle after the beating we already delivered, then I'm eager to oblige them.", progress = "We must hold the line!", completion = "It's good sport, fighting foes larger than yourself. You're happy with your grunts' conduct, Commander?", objectives = "Repel the ogre invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36624] = { id = 36624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashran Appearance", description = "Our base on Ashran is almost complete, commander.\n\nIt would be a huge show of support if you could make a trip out there and put your stamp of approval on their staging area.\n\nI can arrange a flight if you are interested.", completion = "Just a second, pal. Can't you see I'm busy here?\n\nCommander! I didn't think you were actually going to show... I mean... welcome, commander.", objectives = "Speak with Private Tristan at Stormshield in Ashran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36625] = { id = 36625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Discarded Pack" }
quests[36626] = { id = 36626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Host Howell", description = "Lieutenant Howell said you might be showing up.\n\nIt's such an honor to meet you in person. The lieutenant is at the inn, I'll escort you over there.", completion = "Commander {name}, I'm so glad you could make it. It's a true honor, sir.", objectives = "Speak with Lieutenant Howell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36627] = { id = 36627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Frostfire Gun", description = "One of my finest works, {name}! Momma would be so proud of me right now... if she was still in one piece.\n\nWe gotta test this bad boy out though before I'm comfortable letting you run around with it all willy-nilly.\n\nI heard there were some clefthooves out back causing a ruckus.", progress = "Did you manage to subdue those rowdy clefthooves?", completion = "Hmmm... sounds like it still needs a bit more punch. Let me get back to work on it, boss, I'll see what I can do!\n\nGood news is, we know a lot more about the Iron Horde tech now. I made a copy of my notes for ya.", objectives = "Subdue 6 Clefthooves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36628] = { id = 36628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Hammer of Glory" }
quests[36629] = { id = 36629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspiring Ashran", description = "I hope you will find our facilities to be up to your high standards.\n\nThis inn is run by Jaesia Rosecheer, in my opinion this is the best place to hearth in Draenor.\n\nWe have new recruits coming through the portal daily. In fact our latest recruit, Knewbie McGreen just came through the portal today.\n\nIf you are looking to trade for weapons or armor, Vindicator Nuurem will be happy to help.", progress = "How did your walk go?", completion = "Thank you again for taking the time to visit, commander. You have no idea how much it means to us.", objectives = "Speak with Jaesia Rosecheer, Vindicator Nuurem, and Knewbie McGreen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36630] = { id = 36630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Surly Dwarf", description = "Before you go there is someone you might want to talk with.\n\nHe's opinionated, a bit gruff, and very overbearing, but he's the best damn warrior I've met in ages.\n\nHe belongs on the front lines with you, commander. And trust me, he knows it.", completion = "Look, I don't have time for any... Oh, it's you!", objectives = "Speak with Delvar Ironfist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36631] = { id = 36631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Sasha's Stash" }
quests[36632] = { id = 36632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secrets of Gorgrond", description = "Commander, I was dispatched to intercept you.\n\nYrel and Maraad have landed at Wildwood Wash, the rangari base of operations for the area.\n\nYour presence is requested immediately. \n\nWe keep a small feywing presence just east of here. If you speak with the flight master they should be able to provide you safe passage to the Wash.", completion = "Welcome to Gorgrond, Commander. We only just arrived ourselves.", objectives = "Seek Yrel at the Wildwood Wash in Gorgrond. Speak with your Garrison Gryphon Master or the Flight Master at Bastion Rise to fly there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36633] = { id = 36633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delvar Ironfist", objectives = "Well it's about time ye showed up. I'm done slumming around with these new recruits.\n\nMe blade is sharp, me armor is spit shined and I combed me beard this mornin'.\n\nI've been ready for battle since me grandpa Gygax first put an axe in me wee lil hand.\n\nSo whad'ya say, commander?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36634] = { id = 36634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Sniper's Crossbow" }
quests[36635] = { id = 36635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Work Order", description = "Now that you have a profession building, we can start producing work orders for you. When you have the ingredients we need, please come to me to start the first batch.", objectives = "Hand the assistant the reagents to start your first work order from a profession building.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36636] = { id = 36636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint Read" }
quests[36640] = { id = 36640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Followers Obtained" }
quests[36641] = { id = 36641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Alchemy Work Order", description = "Now that the alchemy lab is complete, we can start producing alchemical catalysts for you. When you have the ingredients, please speak with my assistant to start the first work order.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer.", objectives = "Start and collect your first Alchemy work order at the Alchemy Lab.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36642] = { id = 36642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Leatherworking Work Order", description = "Now that the tannery is complete, we can start producing burnished leather for you. When you have the ingredients, please speak with my assistant to start the first work order.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer.", objectives = "Start and collect your first Leatherworking work order at the Tannery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36643] = { id = 36643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Tailoring Work Order", description = "Now that the tailoring emporium is complete, we can start producing hexweave cloth for you. When you have the ingredients, please speak with my assistant to start the first work order.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer.", objectives = "Start and collect your first Tailoring work order at the Tailoring Emporium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36644] = { id = 36644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Jewelcrafting Work Order", description = "Now that the gem boutique is complete, we can start producing taladite crystals for you. When you have the ingredients, please speak with my assistant to start the first work order.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer.", objectives = "Start and collect your first Jewelcrafting work order at the Gem Boutique.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36645] = { id = 36645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Enchanting Work Order", description = "Now that the enchanter's study is complete, we can start producing draenic dust for you. When you have the ingredients, please speak with my assistant to start the first work order.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer.", objectives = "Start and collect your first Enchanting work order at the Enchanter's Study.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36646] = { id = 36646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Engineering Work Order", description = "Now that the engineering works is complete, we can start producing gearspring parts for you. When you have the ingredients, please speak with my assistant to start the first work order.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer.", objectives = "Start and collect your first Engineering work order at the Engineering Works.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36647] = { id = 36647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Inscription Work Order", description = "Now that the scribe's quarters are complete, we can start producing war paints for you. When you have the ingredients, please speak with my assistant to start the first work order.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer.", objectives = "Start and collect your first Inscription work order at the Scribe's Quarters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36648] = { id = 36648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Stonefury Cliffs", description = "Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines.\n\nBodrick Grey has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Bloodmaul ogres at Stonefury Cliffs in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36649] = { id = 36649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Shattrath Harbor", description = "Shattrath City is in the hands of Sargerei forces under the leadership of the traitor Exarch, Socrethar.\n\nMembers of the Sha'tari Defense have been requesting aid against the Shadow Council forces in the eastern portions of the city.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Sargerei forces at Shattrath City in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36650] = { id = 36650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Invasion!", description = "Scouts report that ogre packs march through Shadowmoon Valley. We've left our impression with them, eh Commander?", progress = "We must hold the line!", completion = "Nothing teaches a bully better than a bloody nose! Good fight, Commander. It's an honor to stand with you.", objectives = "Repel the ogre invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36651] = { id = 36651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: SHarvest Crystal" }
quests[36653] = { id = 36653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botani Invasion!", description = "There's a weight in the air. Reminds me of battles in Stranglethorn Valley. Jungle warfare is good for axe-play.", progress = "We must hold the line!", completion = "Is this what a peon feels like? Chopping down trees and pruning unruly hedges all day? And I thought their job was a bore. Hah!", objectives = "Repel the botani invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36654] = { id = 36654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Lost Dwarf" }
quests[36655] = { id = 36655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Horde Invasion!", description = "There's smoke on the horizon... The Iron Horde is coming.", progress = "Repel the Iron Horde invasion.\n\n(Speak with Sergeant Crowler again to begin)", completion = "I don't know what's worse, the brutality of this Iron Horde or the tempered menace of our old foes. It doesn't matter. Neither measures against our strength, Commander.", objectives = "Speak with Sergeant Crowler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
